#if defined(RTA_TEST_EARLY_INTRINSICS) && defined(__clang__) && defined(__x86_64__)
// Model Windows/platform headers loading intrinsics before the DSP FP pragma.
#include <immintrin.h>
#endif
#include "dsp/resampler.h"
#include <bit>
#include <cstdio>
#include <cstdlib>
#include <limits>
using namespace rta::dsp;
// Independent scalar FIR oracle: arbitrary coefficients, not generated by the
// resampler, and one scalar output at a time. Volatile prevents vectorization.
static double oracle(const double* k,size_t stride,const double* h,size_t base,int taps) {
    volatile double acc=0;
    for(int u=0;u<taps;++u) {volatile double product=k[(size_t)u*stride]*h[base-u];acc=acc+product;}
    return acc;
}
int main() {
    size_t checked=0, lanes=0,maxThreads=0;
#if RTA_RESAMPLER_AVX2
    if(resampler_avx2_available()) for(int taps: {1,2,7,8,31,32,211}) {
        std::vector<double> k(taps*8),h(taps);
        for(size_t i=0;i<k.size();++i) k[i]=std::cos(i*.193)*.07;
        for(int i=0;i<taps;++i)h[i]=std::sin(i*.37)*.8;
        for(int special=0;special<6;++special) {
            h[0]=special==0 ? .125 : special==1 ? -0.0 : special==2 ? 1e-310 :
                special==3 ? std::numeric_limits<double>::infinity() : special==4 ?
                -std::numeric_limits<double>::infinity() : std::bit_cast<double>(uint64_t(0x7ff8000000001234));
            double out[4]; resampler_phase4(k.data()+1,8,h.data(),taps-1,taps,out);
            for(int p=0;p<4;++p) {
                double expected=oracle(k.data()+1+p,8,h.data(),taps-1,taps);
                if(std::bit_cast<uint64_t>(expected)!=std::bit_cast<uint64_t>(out[p])) return 3;
                ++checked;
            }
        }
    }
#endif
    for(int channels: {1,2,6}) for(int factor: {2,3,4,5,8,16,32})
    for(int taps: {7,8,31,32}) for(bool cascade: {false,true}) for(bool fixed: {false,true}) {
        ResamplerConfig cfg; cfg.channels=channels; cfg.outRate=cfg.inRate*factor;
        cfg.minTapsPerInput=taps; cfg.applyTapFloor=false; cfg.twoStage=cascade;
        cfg.useFixed=fixed;
        cfg.cpuKernel=ResamplerCpuKernel::Scalar;
        PolyphaseResampler ref(cfg); cfg.cpuKernel=ResamplerCpuKernel::Avx2;
        PolyphaseResampler simd(cfg);
        for(int chunk: {1,3,17,2,65,1,37,257}) {
            std::vector<std::vector<double>> input(channels,std::vector<double>(chunk));
            std::vector<const double*> ip(channels);
            size_t cap=ref.maxOutFrames(chunk);
            std::vector<std::vector<double>> a(channels,std::vector<double>(cap)),b=a;
            std::vector<double*> ap(channels),bp(channels);
            for(int c=0;c<channels;++c) {ip[c]=input[c].data();ap[c]=a[c].data();bp[c]=b[c].data();
                for(int i=0;i<chunk;++i) input[c][i]=chunk==257 ? 0.0 : fixed ? double((i*137+c*23)%1000)/8388608.0 : std::sin((i+checked+1)*.137+c)*.8;}
            size_t n=ref.process(ip.data(),chunk,ap.data());
            if(simd.process(ip.data(),chunk,bp.data())!=n) std::abort();
            lanes+=simd.cpu_simd_outputs_last_block();
            if(ref.cpu_simd_outputs_last_block()!=0) return 4;
            for(int c=0;c<channels;++c)for(size_t i=0;i<n;++i) {
                if(std::bit_cast<uint64_t>(a[c][i])!=std::bit_cast<uint64_t>(b[c][i])) {
                    std::fprintf(stderr,"mismatch ch%d L%d T%d cascade%d idx%zu\n",channels,factor,taps,cascade,i);return 1;}
                ++checked;
            }
        }
    }
    for(unsigned target: {22050u,44100u,48000u,192000u}) {
        ResamplerConfig cfg;cfg.outRate=target;cfg.minTapsPerInput=7;cfg.applyTapFloor=false;
        cfg.cpuKernel=ResamplerCpuKernel::Scalar;PolyphaseResampler ref(cfg);
        cfg.cpuKernel=ResamplerCpuKernel::Auto;PolyphaseResampler simd(cfg);
        double input[17]={.5,-.25,.125};const double* ip[2]={input,input};
        std::vector<double> a(ref.maxOutFrames(17)),b=a,x=a,y=a;
        double* ap[2]={a.data(),x.data()};double* bp[2]={b.data(),y.data()};
        size_t n=ref.process(ip,17,ap);
        if(simd.process(ip,17,bp)!=n || (target==cfg.inRate && simd.cpu_simd_outputs_last_block()!=0)) return 5;
        for(size_t i=0;i<n;++i) {if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i])) return 6;++checked;}
        simd.reset();if(simd.cpu_simd_outputs_last_block()!=0) return 7;
    }
    // Large, uneven partitions exercise actual pool dispatch and vector groups
    // clipped at task boundaries; scalar and single-thread SIMD are both kept.
    for(int channels: {1,2,6}) for(int taps: {210,211}) {
        ResamplerConfig cfg;cfg.channels=channels;cfg.outRate=cfg.inRate*16;
        cfg.minTapsPerInput=taps;cfg.applyTapFloor=false;
        cfg.cpuKernel=ResamplerCpuKernel::Scalar;PolyphaseResampler ref(cfg);
        cfg.cpuKernel=ResamplerCpuKernel::Auto;cfg.cpuParallel=false;PolyphaseResampler serial(cfg);
        cfg.cpuParallel=true;PolyphaseResampler pooled(cfg);
        for(size_t chunk: {1024u,2053u,257u}) {
            std::vector<std::vector<double>> input(channels,std::vector<double>(chunk));
            const size_t cap=ref.maxOutFrames(chunk);
            std::vector<std::vector<double>> a(channels,std::vector<double>(cap)),b=a,c=a;
            std::vector<const double*> ip(channels);
            std::vector<double*> ap(channels),bp(channels),cp(channels);
            for(int channel=0;channel<channels;++channel) {
                ip[channel]=input[channel].data();ap[channel]=a[channel].data();bp[channel]=b[channel].data();cp[channel]=c[channel].data();
                for(size_t i=0;i<chunk;++i)input[channel][i]=chunk==257 ? 0 : std::sin(i*.127+channel)*.7;
            }
            const size_t n=ref.process(ip.data(),chunk,ap.data());
            if(serial.process(ip.data(),chunk,bp.data())!=n || pooled.process(ip.data(),chunk,cp.data())!=n)return 8;
            maxThreads=std::max(maxThreads,pooled.cpu_parallel_threads_last_block());
            if(serial.cpu_parallel_threads_last_block()>1 || pooled.cpu_parallel_threads_last_block()>8)return 9;
            for(int channel=0;channel<channels;++channel)for(size_t i=0;i<n;++i) {
                const auto expected=std::bit_cast<uint64_t>(a[channel][i]);
                if(expected!=std::bit_cast<uint64_t>(b[channel][i]) || expected!=std::bit_cast<uint64_t>(c[channel][i]))return 10;
                checked+=2;
            }
        }
    }
    if(resampler_avx2_available() && lanes==0) return 2;
    std::printf("PASS bit comparisons=%zu actual SIMD outputs=%zu avx2=%d max_pool_threads=%zu\n",checked,lanes,resampler_avx2_available(),maxThreads);
}
